// 原创训练题。范围依据教育部教育考试院2025年公布的15042大纲；现行法补核见coverage-law.json。
export const topics = [];
export const questions = [];
const counters = {};
const chapterNames = { law: '第六章', theory: '第七章', system: '第八章' };
// 各题按实际认知任务标注：r=识记，u=领会，a=应用；章节重点依据大纲“四、本章重点”。
const itemLevels = {
  law: ['aru','uaa','rau','aua','uru','auu','aaa','raa','rrr','rra','aua','rru','rra','rua','ruu','rra','aua','rua'],
  theory: ['rru','rua','rua','ruu','rrr','rua','rua','rua','rua','rra','rua','rua','rua','rra','ura','rua','ruu','ura'],
  system: ['rra','rra','rrr','rra','rra','rra','rur','rua','ruu','rur','rra','rua','rur','rra','rua','rua','rra','rua','rua','ara','ruu','rra','rua','rua'],
};
const coreTopics = { law: new Set([3,4,5,6,7,9,10,11,12,17,18]), theory: new Set([1,2,3,4,5,6,7,8,9,12,13,14,15,16,17,18]), system: new Set(Array.from({length:24},(_,i)=>i+1).filter(i=>i!==21)) };
function add(chapterId, number, title, summary, keyPoints, commonMistake, section, level, sourceIds, shortStem, items) {
  const id = `${chapterId}-${String(number).padStart(2, '0')}`;
  const topic = { id, chapterId, title, summary, keyPoints, commonMistake, outlineRef: `${chapterNames[chapterId]}/${section}/${{ recall: '识记', understand: '领会', apply: '应用' }[level]}`, sourceIds: [...new Set(['outline-2025', ...sourceIds])], level, importance: coreTopics[chapterId].has(number) ? 'core' : 'standard' };
  topics.push(topic);
  function push(question) {
    counters[chapterId] = (counters[chapterId] || 0) + 1;
    questions.push({ id: `sf-${chapterId}-${String(counters[chapterId]).padStart(3, '0')}`, courseId: '15042', chapterId, topicIds: [id], level, sourceId: 'outline-2025', origin: 'original', reviewStatus: 'checked', difficulty: level === 'apply' ? 'advanced' : level === 'understand' ? 'standard' : 'basic', ...question });
  }
  for (const [itemIndex, [stem, correct, ...rest]] of items.entries()) {
    const distractors = rest.slice(0, 3);
    const explanation = rest[3];
    const answer = (questions.filter(q => q.type === 'single').length) % 4;
    const options = [...distractors]; options.splice(answer, 0, correct);
    const questionLevel = {r:'recall',u:'understand',a:'apply'}[itemLevels[chapterId][number-1][itemIndex]];
    push({ type: 'single', stem, options, answer, explanation, level: questionLevel, difficulty: questionLevel === 'apply' ? 'advanced' : questionLevel === 'understand' ? 'standard' : 'basic' });
  }
  push({ type: 'short', stem: shortStem, explanation: `答题应围绕${title}分层展开，先界定概念，再说明条件或联系。${commonMistake}`, keyPoints: [...keyPoints], sampleAnswer: keyPoints.map((point, index) => `${index + 1}. ${point}`).join('\n'), level: level === 'apply' ? 'apply' : 'understand', difficulty: level === 'apply' ? 'advanced' : 'standard' });
}

